class Client:
    def __init__(self, host):
        self.host = host

class AdminClient(Client):
    pass

a = AdminClient("api.local")
print(a.host)

class Animal:
    def sound(self):
        return "..."

class Dog(Animal):
    def sound(self):
        return "woof"

print(Dog().sound(), Animal().sound())

class Base:
    def __init__(self):
        self.name = "base"

class Child(Base):
    def __init__(self, tag):
        self.tag = tag

print(Child("x").name)

class Vehicle:
    def __init__(self, wheels):
        self.wheels = wheels

class Bike(Vehicle):
    def __init__(self):
        super().__init__(2)
        self.bell = True

b = Bike()
print(b.wheels, b.bell)

class Email:
    def send(self):
        return "email"

class Sms:
    def send(self):
        return "sms"

class Alert(Email, Sms):
    pass

print(Alert().send())

class Logger:
    def log(self, msg):
        return f"[log] {msg}"

class TimedLogger(Logger):
    def log(self, msg):
        base = super().log(msg)
        return base + "!"

print(TimedLogger().log("go"))

class Page:
    def __init__(self, url):
        self.url = url

class Home(Page):
    def __init__(self):
        super().__init__()

h = Home()

class A:
    def t(self): return "A"

class B(A):
    def t(self): return "B" + super().t()

class C(A):
    def t(self): return "C" + super().t()

class D(B, C): pass

print(D().t())
